import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const m=JSON.parse('{"title":"Validation and delivery","description":"","frontmatter":{},"headers":[],"relativePath":"validation.md","filePath":"validation.md","lastUpdated":1794376220000}'),r={name:"validation.md"};function s(o,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="validation-and-delivery" tabindex="-1">Validation and delivery <a class="header-anchor" href="#validation-and-delivery" aria-label="Permalink to &quot;Validation and delivery&quot;">​</a></h1><p>The architecture is a hypothesis to test against relevance, responsiveness, consistency, and recovery. The documentation site is the current implementation; the application validation below is planned.</p><h2 id="representative-workload" tabindex="-1">Representative workload <a class="header-anchor" href="#representative-workload" aria-label="Permalink to &quot;Representative workload&quot;">​</a></h2><p>Assemble permission-scoped documents with headings, tables, code, OCR where applicable, ambiguous entity names, acronyms, negated and hypothetical claims, conflicting sources, updates, and deletions. Include exact-identifier and paraphrased questions, relationship questions, unanswerable questions, and long conversations.</p><p>Define corpus size, vector dimensions, update rate, simultaneous chats, hardware, region placement, and model configuration before recording results. Preserve the same relevance target when comparing systems.</p><h2 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Measurements</th></tr></thead><tbody><tr><td>Chat</td><td>First grounded answer token; p50/p95/p99 latency; output gaps; error and interruption rate</td></tr><tr><td>Browser</td><td>First useful content; input latency; long tasks; dropped frames; memory; stable scrolling</td></tr><tr><td>Retrieval</td><td>Filtered latency and recall; fusion quality; graph contribution; reranking cost</td></tr><tr><td>Ingestion</td><td>Stage throughput; source-to-search delay; graph readiness; resource contention</td></tr><tr><td>Knowledge</td><td>Entity-link precision; false merges; relation grounding; supported citations</td></tr><tr><td>Recovery</td><td>Duplicate suppression; stale-attempt rejection; replay gaps; update/delete propagation</td></tr></tbody></table><p>Set numeric budgets after baseline measurements and product requirements. A fast status acknowledgment does not substitute for first grounded text. Node/edge counts do not establish knowledge quality.</p><h2 id="failure-exercises" tabindex="-1">Failure exercises <a class="header-anchor" href="#failure-exercises" aria-label="Permalink to &quot;Failure exercises&quot;">​</a></h2><ul><li>Disconnect and reconnect between snapshot and live subscription; expire retained events.</li><li>Cancel while retrieval or generation completes; restart a gateway; fence an obsolete owner.</li><li>Kill ingestion workers before/after commit; redeliver jobs; replay boundary events.</li><li>Replace a document while extraction is still running; delete its evidence; correct an entity merge.</li><li>Saturate ingestion CPU, model quota, and the database writer while maintaining chat load.</li><li>Exercise long SQLite reads, checkpoint pressure, native-extension failures, and restored backups.</li></ul><h2 id="implementation-sequence" tabindex="-1">Implementation sequence <a class="header-anchor" href="#implementation-sequence" aria-label="Permalink to &quot;Implementation sequence&quot;">​</a></h2><ol><li>Fix scope, artifact schemas, evidence contracts, and terminal-state semantics.</li><li>Build one document-to-chat vertical slice with lexical/vector retrieval and source citations.</li><li>Qualify the SQLite/vector adapter and select a durable workflow engine.</li><li>Add source-backed graph extraction, resolution, corrections, and selective expansion.</li><li>Add useful augmentation and optional retained multi-viewer output based on evaluated requirements.</li><li>Revisit deployment topology only when measurements justify additional boundaries.</li></ol><h2 id="documentation-delivery-gates" tabindex="-1">Documentation delivery gates <a class="header-anchor" href="#documentation-delivery-gates" aria-label="Permalink to &quot;Documentation delivery gates&quot;">​</a></h2><p>Run <code>npm ci</code> and <code>npm run build</code>; VitePress validates generated page links. Preview representative desktop/mobile routes, rendered Mermaid diagrams, search, navigation, color themes, and interactive architecture paths. CI builds the site on pushes and pull requests. Publish source and static output from the same commit, preserving the site&#39;s access policy.</p>',14)])])}const h=t(r,[["render",s]]);export{m as __pageData,h as default};
